SELECT COUNT(*) FROM ${format}_asset WHERE repository_id = #{repositoryId}
    AND deleted_on IS NULL
     AND kind = #{kind}
     AND (${filter});

SELECT  FROM ${format}_asset as asset WHERE repository_id = #{repositoryId}
    AND deleted_on IS NULL
     AND asset_id > #{continuationToken}
     AND kind = #{kind}
     AND (${filter})
ORDER BY asset_id LIMIT #{limit};


SELECT A.asset_id, A.repository_id, A.path, A.kind, A.component_id, A.asset_blob_id,
       A.last_downloaded, A.attributes, A.created, A.last_updated, A.asset_blob_size,
       C.component_id, C.repository_id, C.namespace, C.name, C.kind, C.version,
       C.normalized_version, C.attributes, C.created, C.last_updated, C.entity_version,
       B.*, true AS from_eager_query FROM ${format}_asset as A
  LEFT JOIN ${format}_component C ON C.component_id = A.component_id
  INNER JOIN ${format}_asset_blob B ON B.asset_blob_id = A.asset_blob_id
WHERE A.repository_id = #{repositoryId}
  AND A.deleted_on IS NULL
  AND B.blob_created > #{newerThan}
  AND B.blob_created < #{olderThan}

    AND (
      B.blob_created < #{continuationToken.blobCreated}
      OR (B.blob_created = #{continuationToken.blobCreated} AND A.asset_id > #{continuationToken.assetId})
    )

ORDER BY B.blob_created DESC, A.asset_id ASC
LIMIT #{limit};

