  AND deleted_on IS NULL
   AND asset_id > #{continuationToken}
   AND kind = #{kind}
   AND (${filter})
ORDER BY asset_id LIMIT #{limit};


SELECT a.asset_id, a.repository_id, a.path, a.kind, a.component_id, a.asset_blob_id,
       a.last_downloaded, a.attributes, a.created, a.last_updated, a.asset_blob_size, ab.*
FROM ${format}_asset a INNER JOIN ${format}_asset_blob ab USING (asset_blob_id)
WHERE a.repository_id = #{repositoryId}
AND a.deleted_on IS NULL
 AND ab.added_to_repository >= #{addedToRepository}

 AND (${filter})
ORDER BY ab.added_to_repository LIMIT #{limit}


SELECT a.asset_id, a.repository_id, a.path, a.kind, a.component_id, a.asset_blob_id,
       a.last_downloaded, a.attributes, a.created, a.last_updated, a.asset_blob_size, ab.*
FROM ${format}_asset a INNER JOIN ${format}_asset_blob ab USING (asset_blob_id)
WHERE a.repository_id = #{repositoryId}
AND a.deleted_on IS NULL
AND ab.added_to_repository >= #{startAddedToRepository} AND ab.added_to_repository < #{endAddedToRepository}

 AND (${filter})
ORDER BY ab.added_to_repository LIMIT #{limit}

mapper.insert:
INSERT INTO ${format}_asset (repository_id, path, kind, component_id, asset_blob_id, last_updated, last_downloaded, attributes, asset_blob_size, deleted_on, deleted_by) VALUES (#{asset.repositoryId}, #{asset.path}, #{asset.kind}, #{asset.componentId}, #{asset.assetBlobId}, #{asset.lastUpdated}, #{asset.lastDownloaded}, #{asset.attributes}, #{asset.assetBlob.blobSize}, NULL, NULL) ON CONFLICT ON CONSTRAINT uk_${format}_asset_repository_path DO UPDATE SET kind = #{asset.kind}, component_id = #{asset.componentId}, asset_blob_id = #{asset.assetBlobId}, last_updated = CURRENT_TIMESTAMP, last_downloaded = #{asset.lastDownloaded}, attributes = #{asset.attributes}, asset_blob_size = #{asset.assetBlob.blobSize}, deleted_on = NULL, deleted_by = NULL;
SELECT asset_id FROM ${format}_asset WHERE repository_id = #{asset.repositoryId} AND path = #{asset.path}
WHERE component_id = #{asset.componentId};

MERGE INTO ${format}_asset (repository_id, path, kind, component_id, asset_blob_id, last_updated, last_downloaded,
attributes, asset_blob_size, deleted_on, deleted_by)
KEY (repository_id, path)
VALUES (#{asset.repositoryId}, #{asset.path}, #{asset.kind}, #{asset.componentId}, #{asset.assetBlobId},
#{asset.lastUpdated}, #{asset.lastDownloaded},  #{asset.attributes}, #{asset.assetBlob.blobSize}, NULL, NULL);


  SELECT asset_id FROM ${format}_asset WHERE repository_id = #{asset.repositoryId} AND path = #{asset.path}



   WHERE component_id = #{asset.componentId};

