mapper.update:
UPDATE ${format}_asset
SET deleted_on = CURRENT_TIMESTAMP, deleted_by = #{deletedBy},
    last_updated = CURRENT_TIMESTAMP
WHERE component_id = #{componentId}
  AND deleted_on IS NOT NULL
  AND deleted_on >= #{folderDeleteStarted};

mapper.select:
SELECT A.asset_id, A.repository_id, A.path, A.kind, A.component_id, A.asset_blob_id,
       A.last_downloaded, A.attributes, A.created, A.last_updated, A.asset_blob_size,
       A.deleted_on, A.deleted_by
FROM ${format}_asset A
LEFT JOIN ${format}_component C ON A.component_id = C.component_id
WHERE A.deleted_on IS NOT NULL
AND (A.component_id IS NULL OR C.deleted_on IS NULL OR A.deleted_on < C.deleted_on)
 AND A.repository_id = #{repositoryId}
 AND A.asset_id > #{continuationToken}
ORDER BY A.asset_id ASC LIMIT #{limit};

SELECT  FROM ${format}_asset
WHERE deleted_on IS NOT NULL
 AND repository_id = #{repositoryId}
 AND asset_id > #{continuationToken}
ORDER BY asset_id ASC LIMIT #{limit};

